query:
query MerchantVariantSkuTemplateBinding($after: String, $filter: String!) {
 shop { id }
 activeCount: productsCount(query: "status:active", limit: null) { count precision }
 productVariants(first: 250, after: $after, sortKey: ID, query: $filter) {
   nodes { id sku updatedAt selectedOptions { name value }
     product { id status updatedAt templateSuffix variantsCount { count precision } }
   }
   pageInfo { hasNextPage endCursor }
 }
}
